//! Independent analytic fixtures generated by tool/refs/pdepe/generate.py.
use matrust::{Engine, Matrix};
use std::sync::atomic::Ordering;

const HEAT: &str = "p=@(x,t,u,d) deal(pi^2,d,0); b=@(xl,ul,xr,ur,t) deal(ul,0,pi*exp(-t),1);";
const DIFFUSION: &str = "p=@(x,t,u,d) deal(1,d,0); b=@(xl,ul,xr,ur,t) deal(0,1,ur,0);";

fn matrix(e: &Engine, name: &str) -> Matrix {
    e.variables[name].clone()
}

fn compare(e: &Engine, name: &str, fixture: &str, tol: f64) {
    let a = matrix(e, name);
    assert!(
        a.data().iter().all(|v| v.is_finite()),
        "{name} contains nonfinite values"
    );
    let rows: Vec<Vec<f64>> = fixture
        .lines()
        .map(|line| {
            line.split_whitespace()
                .map(|v| v.parse().unwrap())
                .collect()
        })
        .collect();
    assert_eq!(a.rows(), rows.len());
    assert_eq!(a.cols(), rows[0].len());
    let mut worst = 0f64;
    for (i, row) in rows.iter().enumerate() {
        for (j, expected) in row.iter().enumerate() {
            worst = worst.max((a.get(i, j) - expected).abs());
        }
    }
    eprintln!("{name}: max analytic error {worst:.9e}, bound {tol:.9e}");
    assert!(worst < tol, "{name} max error {worst}, bound {tol}");
}

#[test]
fn documented_heat_problem_matches_analytic_solution() {
    let mut e = Engine::default();
    e.execute(&format!("{HEAT} x=linspace(0,1,41); t=[0 0.1 0.5 1]; sol=pdepe(0,p,@(x) sin(pi*x),b,x,t,odeset('RelTol',1e-6,'AbsTol',1e-8));")).unwrap();
    assert_eq!(matrix(&e, "sol").dims().as_ref(), &[4, 41]);
    compare(&e, "sol", include_str!("fixtures/pdepe/heat.tsv"), 1e-3);
}

#[test]
fn coupled_system_preserves_component_pages_and_squeeze() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal([1;2],[d(1);2*d(2)],[u(2);-2*u(1)]); b=@(xl,ul,xr,ur,t) deal(ul,[0;0],ur,[0;0]); sol=pdepe(0,p,@(x) [sin(pi*x);0],b,linspace(0,1,41)',[0;0.02;0.1],odeset('RelTol',1e-6,'AbsTol',[1e-8;1e-9])); page=sol(:,:,2); cut=squeeze(sol(2,:,:)); shape=size(sol);").unwrap();
    assert_eq!(matrix(&e, "sol").dims().as_ref(), &[3, 41, 2]);
    assert_eq!(matrix(&e, "page").dims().as_ref(), &[3, 41]);
    assert_eq!(matrix(&e, "cut").dims().as_ref(), &[41, 2]);
    assert_eq!(matrix(&e, "shape").data(), &[3., 41., 2.]);
    compare(&e, "sol", include_str!("fixtures/pdepe/coupled.tsv"), 3e-4);
}

#[test]
fn cylindrical_origin_matches_bessel_eigenfunction() {
    let mut e = Engine::default();
    // Left coefficients deliberately prescribe an impossible condition: ignored at x=0.
    e.execute("p=@(x,t,u,d) deal(1,d,0); b=@(xl,ul,xr,ur,t) deal(123,0,ur,0); sol=pdepe(1,p,@(x) besselj(0,2.404825557695773*x),b,linspace(0,1,41),[0 0.02 0.1],odeset('RelTol',1e-6,'AbsTol',1e-8));").unwrap();
    compare(&e, "sol", include_str!("fixtures/pdepe/cylinder.tsv"), 1e-3);
}

#[test]
fn spherical_origin_matches_sinc_eigenfunction() {
    let folder = tempfile::tempdir_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    std::fs::write(
        folder.path().join("sphereic.m"),
        "function u=sphereic(x)\nif x==0\nu=1;\nelse\nu=sin(pi*x)/(pi*x);\nend\nend\n",
    )
    .unwrap();
    let mut e = Engine::default();
    e.set_function_directory(folder.path()).unwrap();
    e.execute(&format!("{DIFFUSION} sol=pdepe(2,p,@sphereic,b,linspace(0,1,41),[0 0.02 0.1],odeset('RelTol',1e-6,'AbsTol',1e-8));")).unwrap();
    compare(&e, "sol", include_str!("fixtures/pdepe/sphere.tsv"), 1e-3);
}

#[test]
fn polar_manufactured_polynomial_on_nonuniform_mesh() {
    for m in [1, 2] {
        let mut e = Engine::default();
        e.execute(&format!("p=@(x,t,u,d) deal(1,d,0); b=@(xl,ul,xr,ur,t) deal(99,0,ur-1-xr^2-2*({m}+1)*t,0); x=[0 0.03 0.12 0.3 0.55 0.8 1]; t=[0 0.1 0.4]; sol=pdepe({m},p,@(x) 1+x^2,b,x,t,odeset('RelTol',1e-7,'AbsTol',1e-9));")).unwrap();
        let x = matrix(&e, "x");
        let t = matrix(&e, "t");
        let a = matrix(&e, "sol");
        for j in 0..x.len() {
            for i in 0..t.len() {
                let expected = 1. + x.data()[j].powi(2) + 2. * (m + 1) as f64 * t.data()[i];
                assert!(
                    (a.get(i, j) - expected).abs() < 2e-5,
                    "m={m}, i={i}, j={j}, {} vs {expected}",
                    a.get(i, j)
                );
            }
        }
    }
}

#[test]
fn regular_annular_geometries_preserve_stationary_fitted_solutions() {
    for (m, ic) in [(1, "log(x)"), (2, "1./x")] {
        let mut e = Engine::default();
        e.execute(&format!("p=@(x,t,u,d) deal(1,d,0); ic=@(x) {ic}; b=@(xl,ul,xr,ur,t) deal(ul-ic(xl),0,ur-ic(xr),0); x=[1 1.05 1.2 1.7 2]; sol=pdepe({m},p,ic,b,x,[0 0.1 1]); expected=ic(x);")).unwrap();
        let a = matrix(&e, "sol");
        let expected = matrix(&e, "expected");
        for j in 0..a.cols() {
            for i in 0..a.rows() {
                assert!((a.get(i, j) - expected.data()[j]).abs() < 1e-9);
            }
        }
    }
}

#[test]
fn elliptic_component_is_initialized_and_solved_as_a_constraint() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal([1;0],d,[0;pi^2*u(1)]); b=@(xl,ul,xr,ur,t) deal(ul,[0;0],ur,[0;0]); x=linspace(0,1,31); t=[0 0.02 0.1]; sol=pdepe(0,p,@(x) [sin(pi*x);0],b,x,t,odeset('RelTol',1e-6,'AbsTol',1e-8));").unwrap();
    let a = matrix(&e, "sol");
    let x = matrix(&e, "x");
    let t = matrix(&e, "t");
    for j in 0..x.len() {
        for i in 0..t.len() {
            let expected = (-std::f64::consts::PI.powi(2) * t.data()[i]).exp()
                * (std::f64::consts::PI * x.data()[j]).sin();
            for k in 0..2 {
                assert!(
                    (a.get(i, j + 31 * k) - expected).abs() < 2e-3,
                    "i={i}, j={j}, k={k}: {} vs {expected}",
                    a.get(i, j + 31 * k)
                );
            }
        }
    }
    assert!((a.get(0, 15 + 31) - 1.).abs() < 2e-3);
}

#[test]
fn nonlinear_capacity_and_source_and_two_time_outputs() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal(1+u^2,d,-(1+u^2)*u); b=@(xl,ul,xr,ur,t) deal(0,1,0,1); sol=pdepe(0,p,@(x) 1,b,[0 0.1 0.4 1],[0 1],odeset('RelTol',1e-7,'AbsTol',1e-9));").unwrap();
    let a = matrix(&e, "sol");
    assert_eq!(a.dims().as_ref(), &[2, 4]);
    for j in 0..4 {
        assert!((a.get(1, j) - (-1f64).exp()).abs() < 2e-6);
    }
}

#[test]
fn time_dependent_dirichlet_conditions_and_nonzero_initial_time() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal(1,d,1); b=@(xl,ul,xr,ur,t) deal(ul-xl-t,0,ur-xr-t,0); x=[-1 -0.4 0 0.2 1]; t=[2 2.2 3]; sol=pdepe(0,p,@(x) x+2,b,x,t,odeset('RelTol',1e-7,'AbsTol',1e-9));").unwrap();
    let a = matrix(&e, "sol");
    let x = matrix(&e, "x");
    let t = matrix(&e, "t");
    for j in 0..x.len() {
        for i in 0..t.len() {
            assert!((a.get(i, j) - x.data()[j] - t.data()[i]).abs() < 2e-6);
        }
    }
}

#[test]
fn pdeval_uses_the_same_basis_and_preserves_query_shape() {
    let mut e = Engine::default();
    e.execute("[u,d]=pdeval(0,[0 1 2],[0 1 3],[2 0 0.5 1]); [uc,dc]=pdeval(0,[0 1 2],[0;1;3],[0;0.5;2]); [emptyu,emptyd]=pdeval(0,[0 1 2],[0 1 3],[]); h=@pdeval; [hu,hd]=h(0,[0 1 2],[0 1 3],0.5);").unwrap();
    assert_eq!(matrix(&e, "u").data(), &[3., 0., 0.5, 1.]);
    assert_eq!(matrix(&e, "d").data(), &[2., 1., 1., 2.]);
    assert_eq!(matrix(&e, "uc").dims().as_ref(), &[3, 1]);
    assert_eq!(matrix(&e, "dc").data(), &[1., 1., 2.]);
    assert_eq!(matrix(&e, "emptyu").len(), 0);
    assert_eq!(matrix(&e, "emptyd").len(), 0);
    assert_eq!(matrix(&e, "hu").data(), &[0.5]);
    assert_eq!(matrix(&e, "hd").data(), &[1.]);
    for m in [1, 2] {
        e.execute(&format!(
            "[pu,pd]=pdeval({m},[0 0.1 0.4 1],[0 0.01 0.16 1],[0 0.05 0.3 0.7 1]);"
        ))
        .unwrap();
        for (i, x) in [0f64, 0.05, 0.3, 0.7, 1.].iter().enumerate() {
            assert!((matrix(&e, "pu").data()[i] - x * x).abs() < 1e-12);
            assert!((matrix(&e, "pd").data()[i] - 2. * x).abs() < 1e-12);
        }
    }
    for (m, ic, derivative) in [(1, "log(x)", "1/q"), (2, "1./x", "-1/q^2")] {
        e.execute(&format!(
            "x=[1 1.2 2]; q=1.6; [u,d]=pdeval({m},x,{ic},q); refd={derivative};"
        ))
        .unwrap();
        let expected = if m == 1 { 1.6f64.ln() } else { 1. / 1.6 };
        assert!((matrix(&e, "u").data()[0] - expected).abs() < 1e-12);
        assert!((matrix(&e, "d").data()[0] - matrix(&e, "refd").data()[0]).abs() < 1e-12);
    }
}

#[test]
fn pdeval_can_interpolate_solver_rows() {
    let mut e = Engine::default();
    e.execute(&format!("{HEAT} x=linspace(0,1,41); sol=pdepe(0,p,@(x) sin(pi*x),b,x,[0 0.1 1]); [u,d]=pdeval(0,x,sol(2,:),[0.1125 0.3625 0.6125 0.8625]);")).unwrap();
    for (i, x) in [0.1125f64, 0.3625, 0.6125, 0.8625].iter().enumerate() {
        assert!(
            (matrix(&e, "u").data()[i] - (-0.1f64).exp() * (std::f64::consts::PI * x).sin()).abs()
                < 2e-3
        );
        assert!(
            (matrix(&e, "d").data()[i]
                - (-0.1f64).exp() * std::f64::consts::PI * (std::f64::consts::PI * x).cos())
            .abs()
                < 1e-2
        );
    }
}

#[test]
fn bad_arguments_and_unsupported_options_are_rejected() {
    let mut e = Engine::default();
    e.execute(DIFFUSION).unwrap();
    for (source, fragment) in [
        ("pdepe()", "pdepe expects"),
        ("pdepe(3,p,@(x) 0,b,[0 0.5 1],[0 1])", "m must"),
        ("pdepe(0,1,@(x) 0,b,[0 0.5 1],[0 1])", "function handle"),
        ("pdepe(0,p,@(x) 0,b,[0 1],[0 1])", "xmesh must have"),
        ("pdepe(0,p,@(x) 0,b,[0 1 0.5],[0 1])", "strictly increasing"),
        ("pdepe(1,p,@(x) 0,b,[-1 0 1],[0 1])", "nonnegative"),
        ("pdepe(0,p,@(x) 0,b,[0 0.5 Inf],[0 1])", "finite"),
        ("pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 0])", "tspan"),
        ("pdepe(0,p,@(x) 0,b,[0 0.5 1],[1 0])", "tspan"),
        (
            "pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1],odeset('RelTol',-1))",
            "RelTol",
        ),
        (
            "pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1],odeset('AbsTol',[1 2]))",
            "AbsTol",
        ),
        (
            "pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1],odeset('Events',@(t,u) 1))",
            "not supported",
        ),
        ("pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1],7)", "odeset"),
        (
            "[a,z]=pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1])",
            "too many output",
        ),
        ("pdeval(0,[0 1 2],[1 2],[0 1])", "one value"),
        ("pdeval(0,[0 1 2],[1 2 3],3)", "within xmesh"),
        ("pdeval(0,[0 1 2],[1 2 3],[0 1;1 2])", "vector"),
        ("pdeval(0,[0 1 2],[1 2 3],NaN)", "finite"),
        ("[a,b,c]=pdeval(0,[0 1 2],[1 2 3],1)", "too many output"),
    ] {
        let err = e.execute(source).unwrap_err();
        assert!(err.contains(fragment), "{source}: {err}");
    }
}

#[test]
fn malformed_callbacks_and_work_limits_are_rejected() {
    let mut e = Engine::default();
    e.execute(DIFFUSION).unwrap();
    for (source, fragment) in [
        ("pdepe(0,p,@(x) [1 2],b,[0 0.5 1],[0 1])", "column vector"),
        ("pdepe(0,p,@(x) NaN,b,[0 0.5 1],[0 1])", "finite"),
        (
            "pdepe(0,@(x,t,u,d) deal(-1,d,0),@(x) 0,b,[0 0.5 1],[0 1])",
            "nonnegative",
        ),
        (
            "pdepe(0,@(x,t,u,d) deal(0,d,0),@(x) 0,b,[0 0.5 1],[0 1])",
            "parabolic",
        ),
        (
            "pdepe(0,@(x,t,u,d) deal([1;1],d,0),@(x) 0,b,[0 0.5 1],[0 1])",
            "length 1",
        ),
        (
            "pdepe(0,p,@(x) 0,@(xl,ul,xr,ur,t) deal(ul,0,ur,[0;0]),[0 0.5 1],[0 1])",
            "length 1",
        ),
        ("pdepe(0,p,@(x) zeros(17,1),b,[0 0.5 1],[0 1])", "equations"),
        ("pdepe(0,p,@(x) 0,b,linspace(0,1,513),[0 1])", "xmesh"),
        ("pdepe(0,p,@(x) 0,b,[0 0.5 1],linspace(0,1,10001))", "tspan"),
        (
            "pdepe(0,p,@(x) 0,b,linspace(0,1,512),linspace(0,1,10000))",
            "output",
        ),
    ] {
        let err = e.execute(source).unwrap_err();
        assert!(err.contains(fragment), "{source}: {err}");
    }
}

#[test]
fn cancellation_is_polled_inside_callbacks_and_solver_recovers_after_errors() {
    let mut e = Engine::default();
    e.execute(DIFFUSION).unwrap();
    let cancelled = e.cancellation();
    let signal = cancelled.clone();
    let canceller = std::thread::spawn(move || {
        std::thread::sleep(std::time::Duration::from_millis(10));
        signal.store(true, Ordering::Relaxed);
    });
    let result = e.execute("sol=pdepe(0,p,@(x) sin(pi*x),b,linspace(0,1,512),[0 0.01 1000]);");
    canceller.join().unwrap();
    let error = result.unwrap_err();
    assert!(error.to_lowercase().contains("cancel"), "{error}");
    cancelled.store(false, Ordering::Relaxed);
    assert!(
        e.execute("sol=pdepe(0,@(x,t,u,d) deal(1,NaN,0),@(x) 0,b,[0 0.5 1],[0 1]);")
            .is_err()
    );
    e.execute("sol=pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 1]);")
        .unwrap();
    assert_eq!(matrix(&e, "sol").data(), &[0.; 6]);
}

#[test]
fn help_pages_and_public_function_names_exist() {
    for name in ["pdepe", "pdeval"] {
        assert!(matrust::session::FUNCTIONS.contains(&name));
        assert!(matrust::help::summary(name).is_some());
        let page = Engine::default()
            .execute(&format!("help {name}"))
            .unwrap()
            .output
            .join("\n");
        assert!(page.contains("Syntax:"));
        assert!(page.contains("Differences from MATLAB:"));
    }
}

#[test]
fn discontinuous_diffusivity_conserves_flux_across_a_mesh_interface() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal(1,(1+3*(x>0.5))*d,0); ic=@(x) (x<=0.5).*x+(x>0.5).*(0.5+(x-0.5)/4); b=@(xl,ul,xr,ur,t) deal(ul,0,ur-0.625,0); x=[0 0.1 0.3 0.5 0.6 0.85 1]; sol=pdepe(0,p,ic,b,x,[0 0.1 1]); expected=ic(x); [u,d]=pdeval(0,x,sol(3,:),[0.2 0.7]);").unwrap();
    let a = matrix(&e, "sol");
    for j in 0..a.cols() {
        for i in 0..a.rows() {
            assert!((a.get(i, j) - matrix(&e, "expected").data()[j]).abs() < 1e-9);
        }
    }
    assert!((matrix(&e, "d").data()[0] - 1.).abs() < 1e-10);
    assert!((matrix(&e, "d").data()[1] - 0.25).abs() < 1e-10);
}

#[test]
fn changing_boundary_type_is_reported_explicitly() {
    let mut e = Engine::default();
    let error = e.execute("p=@(x,t,u,d) deal(1,d,0); b=@(xl,ul,xr,ur,t) deal(ul,t,ur,0); sol=pdepe(0,p,@(x) 0,b,[0 0.5 1],[0 0.1 1]);").unwrap_err();
    assert!(error.contains("boundary q pattern"), "{error}");
}

#[test]
fn polar_system_ignores_unused_left_boundary_outputs() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal([1;1],d,[0;0]); b=@(xl,ul,xr,ur,t) deal([],NaN,ur-[1;2],[0;0]); sol=pdepe(2,p,@(x) [1;2],b,[0 0.1 0.4 1],[0 0.1 1]);").unwrap();
    let a = matrix(&e, "sol");
    for j in 0..4 {
        for i in 0..3 {
            assert!((a.get(i, j) - 1.).abs() < 1e-10);
            assert!((a.get(i, j + 4) - 2.).abs() < 1e-10);
        }
    }
}

#[test]
fn nonzero_left_boundary_uses_flux_rather_than_the_derivative() {
    let mut e = Engine::default();
    e.execute("p=@(x,t,u,d) deal(1,3*d,0); b=@(xl,ul,xr,ur,t) deal(-3,1,ur-1,0); x=[0 0.1 0.3 0.7 1]; sol=pdepe(0,p,@(x) x,b,x,[0 0.1 1]);").unwrap();
    let a = matrix(&e, "sol");
    for j in 0..5 {
        for i in 0..3 {
            assert!((a.get(i, j) - matrix(&e, "x").data()[j]).abs() < 1e-10);
        }
    }
}

#[test]
fn pdeval_preserves_nodal_values_with_large_dynamic_range() {
    let mut e = Engine::default();
    e.execute("[u,d]=pdeval(0,[0 1 2],[0 1e300 1e-300],[0 1 2]);")
        .unwrap();
    assert_eq!(matrix(&e, "u").data(), &[0., 1e300, 1e-300]);
    assert!(matrix(&e, "d").data().iter().all(|v| v.is_finite()));
}
